from graphlib import TopologicalSorter, CycleError

good = {"c": ["a", "b"], "b": ["a"], "a": []}
loop = {"x": ["y"], "y": ["x"]}

def order_of(graph):
    return list(TopologicalSorter(graph).static_order())

def has_cycle(graph):
    try:
        order_of(graph)
    except CycleError:
        return True
    return False

print(order_of(good))
print(has_cycle(good))
print(has_cycle(loop))
